use super::*;

// ============================================================
// ISO 9660 integration tests (bsdtar-written fixtures)
// ============================================================
//
// Reference images generated by libarchive's ISO9660 writer
// (`bsdtar -cf out.iso --format iso9660`), committed under
// `tests/fixtures/iso9660/`:
//   - bsdtar-plain.iso:      plain ISO9660 (uppercase names, `;1` versions)
//   - bsdtar-rockridge.iso:  Rock Ridge 1.12 + SUSP 1.10 extensions
//   - bsdtar-joliet.iso:     Joliet supplementary volume descriptor
// Source tree: iso-tree/{hello.txt(14B), bigfile.dat(3000B),
// sub/{one.dat(1B), deep/two.dat(1B)}, link.txt -> hello.txt}.

const PLAIN: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-plain.iso");
const RR: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-rockridge.iso");
const JOLIET: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-joliet.iso");

fn find<'a>(img: &'a iso9660::decode::IsoImage, path: &str) -> &'a iso9660::decode::IsoEntry {
    img.entries
        .iter()
        .find(|e| e.name == path)
        .unwrap_or_else(|| panic!("missing entry {path}"))
}

#[test]
fn test_iso9660_plain_image() {
    let img = iso9660::decode::decode(PLAIN).unwrap();
    assert_eq!(img.volume_id, "CDROM");
    assert!(!img.has_rock_ridge);
    // bsdtar emits a Joliet SVD even for the default writer;
    // plain names win only when no usable alternate tree exists.
    let hello = find(&img, "ISO_TREE/HELLO.TXT");
    assert_eq!(hello.kind, iso9660::decode::IsoKind::File);
    assert_eq!(hello.data.len(), 14);
    // directory names also lose the `;version` suffix
    let sub = find(&img, "ISO_TREE/SUB");
    assert_eq!(sub.kind, iso9660::decode::IsoKind::Directory);
    let two = find(&img, "ISO_TREE/SUB/DEEP/TWO.DAT");
    assert_eq!(two.data.len(), 1);
    // no '.'/'..' pseudo entries
    assert!(img.entries.iter().all(|e| e.name != "." && e.name != ".."));
}

#[test]
fn test_iso9660_rockridge_image() {
    let img = iso9660::decode::decode(RR).unwrap();
    assert!(img.has_rock_ridge);

    // NM names: lowercase POSIX names from the Rock Ridge tree
    let hello = find(&img, "iso-tree/hello.txt");
    assert_eq!(hello.kind, iso9660::decode::IsoKind::File);
    assert_eq!(hello.data, b"hello iso9660\n");

    // multi-sector file (3000 bytes crosses a 2048 boundary)
    let big = find(&img, "iso-tree/bigfile.dat");
    assert_eq!(big.data.len(), 3000);
    assert!(big.data.iter().any(|&b| b != 0));

    // nested directories
    let deep = find(&img, "iso-tree/sub/deep/two.dat");
    assert_eq!(deep.data.len(), 1);

    // PX entries carry POSIX modes (444 file / 555 dir on RO media)
    let sub = find(&img, "iso-tree/sub");
    assert_eq!(sub.mode & 0o170000, 0o040000);
    assert_eq!(sub.mode & 0o111, 0o111);
    assert_eq!(hello.mode & 0o170000, 0o100000);

    // SL symlink: target recorded as entry data
    let link = find(&img, "iso-tree/link.txt");
    assert_eq!(link.kind, iso9660::decode::IsoKind::Symlink);
    assert_eq!(link.data, b"hello.txt");
}

#[test]
fn test_iso9660_joliet_image() {
    let img = iso9660::decode::decode(JOLIET).unwrap();
    assert!(img.has_joliet);
    // Joliet UCS-2 names keep the original casing
    let hello = find(&img, "iso-tree/hello.txt");
    assert_eq!(hello.data, b"hello iso9660\n");
    let deep = find(&img, "iso-tree/sub/deep/two.dat");
    assert_eq!(deep.data.len(), 1);
    let big = find(&img, "iso-tree/bigfile.dat");
    assert_eq!(big.data.len(), 3000);
}

#[test]
fn test_iso9660_codec_trait() {
    use archive::traits::{ArchiveDecode, ArchiveEntry};
    let codec = iso9660::Iso9660Codec;
    let entries = codec.decode(RR).unwrap();
    assert!(entries.iter().any(|e| e.name() == "iso-tree/hello.txt"));
}

#[test]
fn test_iso9660_rejects_truncated() {
    // shorter than the PVD sector
    assert!(iso9660::decode::decode(&RR[..16 * 2048]).is_err());
    // truncate inside referenced file data (the image uses sectors
    // up to ~32; cutting at sector 30 drops extent payload)
    assert!(iso9660::decode::decode(&RR[..30 * 2048]).is_err());
    // empty input
    assert!(iso9660::decode::decode(&[]).is_err());
}

#[test]
fn test_iso9660_rejects_corrupt() {
    // PVD magic corrupt
    let mut img = RR.to_vec();
    img[16 * 2048 + 1] = b'X';
    assert!(iso9660::decode::decode(&img).is_err());
    // duplicate PVD: point the terminator at a copy of the PVD
    let mut img = RR.to_vec();
    let pvd = img[16 * 2048..17 * 2048].to_vec();
    // find first terminator sector and overwrite
    for s in 17..img.len() / 2048 {
        if img[s * 2048] == 255 {
            img[s * 2048..(s + 1) * 2048].copy_from_slice(&pvd);
            break;
        }
    }
    assert!(iso9660::decode::decode(&img).is_err());
}
